function canMake24(cards: number[]): boolean {
  const ops = [
    (a: number, b: number) => a + b,
    (a: number, b: number) => a - b,
    (a: number, b: number) => a * b,
    (a: number, b: number) => (b === 0 ? NaN : a / b),
  ];
  const perms: number[][] = [];
  const permute = (rest: number[], cur: number[]) => {
    if (!rest.length) { perms.push(cur); return; }
    rest.forEach((x, i) => permute([...rest.slice(0, i), ...rest.slice(i + 1)], [...cur, x]));
  };
  permute(cards, []);
  const is24 = (x: number) => Math.abs(x - 24) < 1e-6;
  for (const [a, b, c, d] of perms) {
    for (const f of ops) for (const g of ops) for (const h of ops) {
      const shapes = [
        h(g(f(a, b), c), d), // ((a b) c) d
        h(f(a, g(b, c)), d), // (a (b c)) d
        g(f(a, b), h(c, d)), // (a b) (c d)
        f(a, h(g(b, c), d)), // a ((b c) d)
        f(a, g(b, h(c, d))), // a (b (c d))
      ];
      if (shapes.some(is24)) return true;
    }
  }
  return false;
}

