class Solution:
    def canMake24(self, cards: List[int]) -> bool:
        from itertools import permutations, product

        def div(a, b):
            return float("nan") if b == 0 else a / b

        ops = [lambda a, b: a + b, lambda a, b: a - b, lambda a, b: a * b, div]
        for a, b, c, d in permutations(cards):
            for f, g, h in product(ops, repeat=3):
                shapes = (
                    h(g(f(a, b), c), d),
                    h(f(a, g(b, c)), d),
                    g(f(a, b), h(c, d)),
                    f(a, h(g(b, c), d)),
                    f(a, g(b, h(c, d))),
                )
                if any(abs(x - 24) < 1e-6 for x in shapes):
                    return True
        return False

