function canMake24(cards: number[]): boolean {
  const EPS = 1e-6;
  const solve = (vals: number[]): boolean => {
    if (vals.length === 1) return Math.abs(vals[0] - 24) < EPS;
    for (let i = 0; i < vals.length; i++) {
      for (let j = i + 1; j < vals.length; j++) {
        const rest = vals.filter((_, k) => k !== i && k !== j);
        const a = vals[i], b = vals[j];
        const results = [a + b, a - b, b - a, a * b];
        if (Math.abs(b) > EPS) results.push(a / b);
        if (Math.abs(a) > EPS) results.push(b / a);
        for (const x of results) {
          rest.push(x);
          if (solve(rest)) return true;
          rest.pop();
        }
      }
    }
    return false;
  };
  return solve(cards.slice());
}

