class Solution:
    def canMake24(self, cards: List[int]) -> bool:
        EPS = 1e-6

        def solve(vals):
            if len(vals) == 1:
                return abs(vals[0] - 24) < EPS
            for i in range(len(vals)):
                for j in range(i + 1, len(vals)):
                    rest = [v for k, v in enumerate(vals) if k != i and k != j]
                    a, b = vals[i], vals[j]
                    results = [a + b, a - b, b - a, a * b]
                    if abs(b) > EPS:
                        results.append(a / b)
                    if abs(a) > EPS:
                        results.append(b / a)
                    for x in results:
                        if solve(rest + [x]):
                            return True
            return False

        return solve([float(c) for c in cards])

